// AUTO-GENERATED by `mise run gen-types`. Do not edit manually.
type Amount = string; // rust_decimal money — always a decimal string

/**
 * Preferences that follow the *user*, not the vault: they must survive opening
 * a different vault, so they are stored next to the app, not inside the doc.
 */
type AppSettings = { theme: Theme, locale: Locale, 
/**
 * ISO 4217 code the whole portfolio is valued in (e.g. `usd`, `rub`).
 */
base_currency: string, 
/**
 * Currencies offered on hover next to any price. Empty = no tooltip.
 */
favorite_currencies: Array<string>, };

/**
 * Loose asset identification: enough to rebuild an [`AssetRef`] cache key
 * without making the frontend construct a full `quote` field.
 */
type AssetPriceInput = { symbol: string, coingecko_id: string | null, chain: Chain | null, contract: string | null, };

type AssetRef = { symbol: string, name: string, 
/**
 * e.g. `bitcoin` — used by CoinGecko.
 */
coingecko_id: string | null, chain: Chain | null, 
/**
 * Token contract address (for tokens on EVM/Solana-like networks).
 */
contract: string | null, 
/**
 * `base` quote currency symbol for FX peers (e.g. `usd`, `eur`).
 * For crypto this is the network quote (e.g. `btc`, `eth`).
 * Kept authoritative for display only.
 */
quote: string, };

type AssetSearchHit = { symbol: string, name: string, coingecko_id: string | null, chain: Chain | null, contract: string | null, 
/**
 * CoinGecko market-cap rank (0 = unknown).
 */
rank: bigint, };

type AssetStat = { asset: AssetRef, quantity: Amount, price_usd: Amount, value_usd: Amount, };

/**
 * A fill as offered in the "recent trades" dropdown.
 */
type BybitExecution = { symbol: string, side: string, order_type: string, exec_price: string, exec_qty: string, exec_value: string, exec_fee: string, exec_time: string, is_maker: boolean, 
/**
 * Pre-shaped form values, so the frontend never re-derives the swap.
 */
prefill: TradePrefill, };

type BybitExecutionsInput = { category: Category, symbol: string | null, limit: number | null, store_id: string | null, };

/**
 * Never fails: an unconfigured or unreachable key yields an empty list.
 */
type BybitExecutionsResult = { executions: Array<BybitExecution>, notice: string | null, };

/**
 * Last cached USD quote. `ts` is empty when the asset was never priced.
 */
type CachedPrice = { price_usd: Amount, ts: string, };

/**
 * Raw calculator inputs. The UI is expected to pass empty/zero values while
 * the user is still typing — every field is optional in practice.
 */
type CalcInput = { mode: CalcMode, 
/**
 * Source asset symbol, display only.
 */
from_symbol: string, 
/**
 * Target asset symbol, display only.
 */
to_symbol: string, 
/**
 * `Converter`: amount to convert. `Position`: position size.
 */
amount: Amount, 
/**
 * Price of one unit of the source asset. In `Position` mode this is the
 * entry price of the position.
 */
price_in: Amount, 
/**
 * `Converter` only: price of one unit of the target asset.
 */
price_out: Amount, 
/**
 * Take-profit price (`Position` only).
 */
target_price: Amount | null, 
/**
 * Stop-loss price (`Position` only).
 */
stop_price: Amount | null, 
/**
 * Round-trip commission in percent (`"0.1"` = 0.1%).
 */
fee_pct: Amount, };

/**
 * Which set of inputs/outputs [`preview`] should compute.
 */
type CalcMode = "converter" | "position";

/**
 * Ready-to-render result. Fields that do not apply to the chosen mode stay
 * zero; the UI shows an em dash for them.
 */
type CalcResult = { 
/**
 * `amount × price_in` — the notional put in.
 */
gross_in: Amount, 
/**
 * `gross_in × fee_pct / 100`.
 */
fee: Amount, 
/**
 * `gross_in + fee` — what the position really costs.
 */
spent: Amount, 
/**
 * `Converter`: `amount × price_out` before fees.
 */
gross_out: Amount, 
/**
 * `Converter`: `gross_out − fee`.
 */
net_out: Amount, 
/**
 * `Position`: `amount × target_price`.
 */
exit_value: Amount, 
/**
 * `Position`: `exit_value − spent`.
 */
pnl: Amount, 
/**
 * `Position`: `pnl / spent × 100`.
 */
roi_pct: Amount, 
/**
 * `Position`: `amount × (price_in − stop_price)`, floored at zero.
 */
risk: Amount, 
/**
 * `Position`: `risk / spent × 100`.
 */
risk_pct: Amount, };

/**
 * Single OHLCV candle point for charting.
 */
type CandlePoint = { ts: string, open: string, high: string, low: string, close: string, volume: string, };

/**
 * Product type. Bybit requires this on most private endpoints.
 */
type Category = "spot" | "linear" | "inverse";

/**
 * Supported blockchain networks + a pseudo `Fiat` variant.
 *
 * Metadata (CoinGecko identifiers and explorer templates) lives in
 * `ChainInfo`. Adding a network = adding one variant here + one match arm.
 */
type Chain = "bitcoin" | "ethereum" | "bsc" | "solana" | "polygon" | "arbitrum" | "optimism" | "avalanche" | "base" | "tron" | "litecoin" | "dogecoin" | "cardano" | "xrp" | "polkadot" | "cosmos" | "near" | "ton" | "algorand" | "fiat";

type ChangePasswordInput = { current_password: string, new_password: string, };

/**
 * Input to clear a key for a specific store.
 */
type ClearExchangeKeyInput = { store_id: string, };

/**
 * Turn staged fills into real trades (two legs each, like `add_trade`).
 */
type ConfirmPendingImportsInput = { 
/**
 * Empty = confirm everything currently staged.
 */
exec_ids: Array<string>, };

type ConfirmPendingImportsOutput = { confirmed: number, };

type CreateStoreInput = { name: string, kind: StoreKind, color: string, note: string, parent_id: string | null, };

type CreateVaultInput = { path: string, password: string, };

/**
 * Catalog of currencies the base/favourite pickers may offer.
 */
type CurrencyCatalogOutput = { catalog: SupportedCurrencies, 
/**
 * Machine code describing where the list came from: `builtin` when it is
 * the built-in fallback (never fetched), `cached` when the network was
 * unreachable and the last successful fetch was reused, `null` when the
 * providers answered just now.
 */
notice: string | null, };

type DashboardWidgetCfg = { id: string, visible: boolean, order: number, };

/**
 * Output of the dev dump vault command (DEV only).
 */
type DevDumpVaultOutput = { json: string, };

/**
 * Drop staged fills without creating transactions.
 */
type DiscardPendingImportsInput = { 
/**
 * Empty = discard everything currently staged.
 */
exec_ids: Array<string>, };

type DiscardPendingImportsOutput = { discarded: number, };

/**
 * Whether a key is stored. The secret is never part of this response.
 */
type ExchangeKeyStatus = { configured: boolean, 
/**
 * Masked identifier such as `abcd…wxyz`, for the settings screen.
 */
hint: string | null, };

/**
 * A cached FX rate: units of `currency` per 1 USD.
 */
type FxPoint = { currency: string, per_usd: Amount, ts: string, source: string, };

type GetCandlesInput = { symbol: string, interval_min: number, limit: number, };

type GetCandlesOutput = { candles: Array<CandlePoint>, };

type HistoryPoint = { ts: string, ts_ms: bigint, value_usd: Amount, value_base: Amount, };

/**
 * A position of one asset inside one store (хранилище !== актив).
 */
type Holding = { id: string, store_id: string, asset: AssetRef, quantity: Amount, 
/**
 * Optional manual average cost basis per unit (in base currency).
 */
avg_cost: Amount | null, };

/**
 * Fetch every Bybit fill for a store and stage it for user confirmation.
 */
type ImportBybitHistoryInput = { store_id: string, 
/**
 * Safety cap on fetched fills (default 1000, max 10000). The import always
 * sweeps every category the key has access to.
 */
limit: number | null, };

/**
 * How many fills this run newly staged (already-known ids are skipped).
 */
type ImportBybitHistoryOutput = { staged: number, 
/**
 * Machine code: `no_key` | `unreachable` | `rate_limited` |
 * `forbidden_region`.
 */
notice: string | null, };

/**
 * Chain the user picked when the hash alone was ambiguous. Without it the
 * backend never guesses an EVM network.
 */
type InspectTxInput = { tx_hash: string, 
/**
 * `None` for EVM hashes, where a wrong guess would be worse than no data.
 */
network: Chain | null, };

/**
 * Result of a best-effort lookup. `fetched` tells the UI whether to say
 * anything at all; a `false` with no `notice` means "stay silent".
 */
type InspectTxResult = { 
/**
 * `false` when the provider could not be reached or the hash is unusable.
 */
fetched: boolean, info: TxInfo | null, hints: Array<TxFieldHint>, 
/**
 * Why nothing came back, for a quiet inline hint. Never a blocking error.
 */
notice: string | null, };

type ListPendingImportsOutput = { imports: Array<PendingImport>, };

type Locale = "auto" | "en" | "ru";

type NamedValue = { label: string, value_usd: Amount, value_base: Amount, pct: number, };

/**
 * A staged Bybit fill awaiting user confirmation before becoming a trade.
 *
 * Fills land here first and never touch `transactions` until the user
 * confirms them, so a background import can never silently rewrite history.
 * Deduplication key is Bybit's `execId`.
 */
type PendingImport = { 
/**
 * Bybit's execution ID (`execId`) — the deduplication key.
 */
exec_id: string, 
/**
 * Store the fill belongs to.
 */
store_id: string, 
/**
 * Product category: `spot` | `linear` | `inverse`.
 */
category: string, 
/**
 * Pair symbol as Bybit reports it (e.g. `BTCUSDT`).
 */
symbol: string, 
/**
 * `"buy"` or `"sell"`.
 */
side: string, 
/**
 * Asset received.
 */
asset_bought: string, qty_bought: Amount, 
/**
 * Asset given up.
 */
asset_sold: string, qty_sold: Amount, 
/**
 * Fill price of one unit of the base asset.
 */
price: Amount, fee: Amount, 
/**
 * Fee denom; empty when Bybit reported none.
 */
fee_asset: string, 
/**
 * ISO-8601 UTC.
 */
occurred_at: string, 
/**
 * Provenance note shown in the staging UI.
 */
comment: string, };

type PnlLeg = { ts: string, store_id: string, asset_key: string, 
/**
 * Absolute size of the closed-out quantity.
 */
quantity: Amount, pnl_base: Amount, side: string, };

type PortfolioSummary = { base_currency: string, fx_per_usd: Amount, total_usd: Amount, total_base: Amount, assets: Array<AssetStat>, by_chain: Array<NamedValue>, by_store: Array<StoreValue>, };

/**
 * A cached price: one unit of an asset in USD.
 */
type PricePoint = { 
/**
 * `AssetRef::key()`.
 */
asset_key: string, value_usd: Amount, 
/**
 * ISO-8601 UTC.
 */
ts: string, source: string, };

type RealizedPnl = { total_base: Amount, legs: Array<PnlLeg>, };

/**
 * A recently opened vault file.
 */
type RecentVault = { path: string, last_opened: string, exists: boolean, };

type RefreshResult = { prices: number, fx: number, updated_at: string, };

/**
 * Input to select or pick a vault file.
 */
type SelectVaultInput = { path: string, };

/**
 * Stores a read-only key for a specific store. Both fields are written to the
 * encrypted vault and are never echoed back to the frontend.
 */
type SetExchangeKeyInput = { store_id: string, api_key: string, api_secret: string, };

type SetTxPricesInput = { transaction_id: string, price_usd: Amount | null, fx_override: Amount | null, };

/**
 * Vault-scoped settings.
 *
 * The preferences that describe the *user* rather than this particular vault
 * (theme, language, base currency, favourite currencies) live outside the
 * encrypted doc — see [`crate::appconfig::AppSettings`].
 */
type Settings = { 
/**
 * Decimal places used to render balances.
 */
display_decimals: number, dashboard_widgets: Array<DashboardWidgetCfg>, fx_refresh_interval_sec: number, minimize_to_tray: boolean, 
/**
 * Background Bybit import interval in seconds. 0 = disabled. Default 900 (15 min).
 */
bybit_import_interval_sec: number, };

/**
 * A "store"/"platform" (хранилище) — a portfolio container.
 * Important: a store is NOT an asset — it holds holdings (`Holding`).
 */
type Store = { id: string, name: string, kind: StoreKind, 
/**
 * CSS-friendly accent color for the UI (hex, e.g. `#0ea5e9`).
 */
color: string, archived: boolean, 
/**
 * Free-form description shown in the UI.
 */
note: string, 
/**
 * Optional parent store ID for nesting (free tree, any depth).
 */
parent_id: string | null, };

/**
 * Everything the wallet page needs about one store, in a single round trip.
 * Computed on the fly — nothing here is persisted, so the vault format
 * version is unaffected.
 */
type StoreChildRow = { store: Store, value_usd: Amount, value_base: Amount, };

/**
 * What kind of container a store represents.
 */
type StoreKind = "exchange" | "hot_wallet" | "cold_wallet" | "bank" | "cash" | "paper";

/**
 * Everything the wallet page needs about one store, in a single round trip.
 * Computed on the fly — nothing here is persisted, so the vault format
 * version is unaffected.
 */
type StoreOverview = { store: Store, base_currency: string, fx_per_usd: Amount, total_usd: Amount, total_base: Amount, 
/**
 * Total value including all descendants (subtree).
 */
subtree_total_base: Amount, realized_pnl_base: Amount, 
/**
 * Sorted by `value_base`, descending.
 */
positions: Array<StorePosition>, 
/**
 * Direct children with their own values (for tree rendering).
 */
children: Array<StoreChildRow>, tx_count: number, 
/**
 * RFC3339; empty when the store has no transactions.
 */
first_tx_at: string, last_tx_at: string, };

/**
 * A single open position inside one store.
 */
type StorePosition = { asset: AssetRef, quantity: Amount, 
/**
 * Weighted average cost per unit in the base currency, if known.
 */
avg_cost: Amount | null, price_usd: Amount, value_usd: Amount, value_base: Amount, 
/**
 * `(price_base − avg_cost) × |quantity|`; zero when `avg_cost` is unknown.
 */
unrealized_base: Amount, };

/**
 * One store's slice of the portfolio. Unlike [`NamedValue`] it carries the
 * store id so the sidebar can link straight to the wallet page.
 */
type StoreValue = { store_id: string, name: string, value_usd: Amount, value_base: Amount, pct: number, };

/**
 * Currencies the pickers may offer.
 *
 * Built from the public providers at runtime and cached on disk; see
 * [`fallback`] for the degraded case.
 */
type SupportedCurrencies = { 
/**
 * ISO 4217 codes, lowercase.
 */
fiat: Array<string>, 
/**
 * Crypto ticker symbols, lowercase.
 */
crypto: Array<string>, };

type Theme = "auto" | "light" | "dark";

type TradeInput = { store_id: string, sell_symbol: string, sell_name: string, sell_coingecko_id: string | null, sell_chain: Chain | null, sell_contract: string | null, sell_qty: Amount, buy_symbol: string, buy_name: string, buy_coingecko_id: string | null, buy_chain: Chain | null, buy_contract: string | null, buy_qty: Amount, comment: string, 
/**
 * Tags applied to both legs of the trade.
 */
categories: Array<string>, fee: Amount | null, };

/**
 * A fill shaped for the trade form: what was sold, what was bought, costs.
 */
type TradePrefill = { 
/**
 * `buy` when the user acquired the base asset, `sell` when they gave it up.
 */
side: string, symbol: string, asset_sold: string | null, qty_sold: string | null, asset_bought: string | null, qty_bought: string | null, price: string | null, fee: string | null, fee_asset: string | null, 
/**
 * ISO-8601 UTC, ready for the form's date field.
 */
occurred_at: string | null, comment: string | null, };

/**
 * A single transaction record.
 *
 * Sign convention:
 * - `amount > 0` — asset flows **into** `store_id` (unless kind is `Expense` or
 *   `Payment`, where positive means spent/out).
 * - `amount < 0` — asset flows **out** of `store_id`.
 * - `Transfer` legs: from-leg has negative amount on `store_id` + `to_store_id` set;
 *   to-leg has positive amount with `store_id == source leg's to_store_id`.
 */
type Transaction = { id: string, kind: TxKind, asset: AssetRef, amount: Amount, 
/**
 * Principal store (origin for expense, destination for income).
 */
store_id: string, 
/**
 * Counterpart store for transfers/trades.
 */
to_store_id: string | null, network: Chain | null, 
/**
 * On-chain tx hash (link to explorer).
 */
tx_hash: string | null, 
/**
 * User-defined tags for this transaction. A transaction may carry any
 * number of them — one payment can be `food` *and* `weekend` — and every
 * tag is a member of `VaultDoc::categories`. Normalized (trimmed,
 * lowercased, deduplicated) by the service before it is stored.
 */
categories: Array<string>, 
/**
 * User note — REQUIRED field on the UI, free-form text here. (see README/docs)
 */
comment: string, 
/**
 * ISO-8601 UTC timestamp, lexicographically sortable.
 */
timestamp: string, 
/**
 * Fee paid, in `fee_asset` units (or the tx asset when None).
 */
fee: Amount | null, fee_asset: string | null, 
/**
 * Group id shared across legs of the same transfer/trade/paper run.
 */
group_id: string | null, 
/**
 * Price of one unit of `asset` in USD at tx time (stamped by backend).
 */
price_usd: Amount | null, 
/**
 * Price of one unit of `asset` in the base currency at tx time.
 */
price_base: Amount | null, 
/**
 * Optional user-provided exchange rate override at tx time (base per 1 usd).
 */
fx_override: Amount | null, };

type TransferInput = { from_store_id: string, to_store_id: string, symbol: string, name: string, coingecko_id: string | null, chain: Chain | null, contract: string | null, amount: Amount, comment: string, 
/**
 * Tags applied to both legs of the transfer.
 */
categories: Array<string>, network: Chain | null, tx_hash: string | null, fee: Amount | null, };

/**
 * A single field suggestion for the trade form.
 *
 * Everything is optional and unvalidated on purpose: the form only fills in
 * what the provider actually returned.
 */
type TxFieldHint = { field: string, value: string, };

/**
 * Everything we could learn about a transaction. All fields optional: a
 * partial answer is still useful and is always safe to display.
 */
type TxInfo = { tx_hash: string, 
/**
 * `None` when the shape alone cannot identify the network.
 */
network: Chain | null, 
/**
 * Set when the user must resolve an ambiguous `0x…` hash themselves.
 */
needs_manual_network: boolean, explorer_url: string | null, 
/**
 * ISO-8601 UTC when the transaction was mined/confirmed.
 */
occurred_at: string | null, status: string | null, asset_in: string | null, amount_in: string | null, asset_out: string | null, amount_out: string | null, fee: string | null, fee_asset: string | null, };

/**
 * High-level meaning of a transaction.
 */
type TxKind = "income" | "expense" | "payment" | "transfer" | "trade" | "fee" | "paper_trade";

type TxnInput = { kind: TxKind, symbol: string, name: string, coingecko_id: string | null, chain: Chain | null, contract: string | null, 
/**
 * Always a positive magnitude; sign is applied by the backend per kind.
 */
amount: Amount, store_id: string, comment: string, 
/**
 * User tags; any number of them, normalized by the backend.
 */
categories: Array<string>, timestamp: string | null, tx_hash: string | null, network: Chain | null, price_usd: Amount | null, fee: Amount | null, };

type UnlockInput = { path: string, password: string, };

/**
 * Partial update: only the fields present in the payload are touched.
 */
type UpdateAppSettingsInput = { theme: Theme | null, locale: Locale | null, base_currency: string | null, favorite_currencies: Array<string> | null, };

type UpdateCommentInput = { transaction_id: string, comment: string, };

/**
 * Partial update of the **vault-scoped** settings.
 */
type UpdateSettingsInput = { display_decimals: number | null, dashboard_widgets: Array<DashboardWidgetCfg> | null, fx_refresh_interval_sec: number | null, minimize_to_tray: boolean | null, 
/**
 * Background Bybit poll interval; `0` disables it (D2.4).
 */
bybit_import_interval_sec: number | null, };

type UpdateStoreInput = { id: string, name: string, color: string, note: string, parent_id: string | null, };

/**
 * Full plaintext vault document. Serialized as JSON (dev) or bincode (prod).
 */
type VaultDoc = { version: number, id: string, created_at: string, settings: Settings, stores: Array<Store>, holdings: Array<Holding>, transactions: Array<Transaction>, categories: Array<string>, price_cache: Array<PricePoint>, fx_cache: Array<FxPoint>, 
/**
 * Staged Bybit fills awaiting user confirmation (D2.4).
 */
pending_imports: Array<PendingImport>, };

type VaultInfo = { path: string, doc_version: number, id: string, created_at: string, format: string, base_currency: string, };

/**
 * What the unlock screen needs to know about the app.
 */
type VaultStatus = { path: string, exists: boolean, unlocked: boolean, info: VaultInfo | null, };
